import React, { useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import './Meeting.css';

function Meeting({ stream, handleMuteUnmute, handleOpenCloseCamera }) {
  const userVideo = useRef();
  const navigate = useNavigate();

  useEffect(() => {
    if (stream) {
      // Use the passed stream instead of requesting a new one
      userVideo.current.srcObject = stream;
    }
  }, [stream]);

  const handleLeave = () => {
    navigate('/');
  };

  return (
    <div className="App">
      <main>
        <video ref={userVideo} id="localVideo" autoPlay muted></video>
        <video id="remoteVideo" autoPlay></video>
        <div>
          <button onClick={handleMuteUnmute}>Mute/Unmute</button>
          <button onClick={() => handleOpenCloseCamera(userVideo)}>Open/Close Camera</button>
          <button id="callButton" onClick={handleLeave}>Leave</button>
        </div>
      </main>
    </div>
  );
}

export default Meeting;
